function loadState(): StoredState {
  try {
    const raw = window.localStorage.getItem('heatt-state')
    if (!raw) return defaultState
    const parsed = JSON.parse(raw) as Partial<StoredState>
    return { ...defaultState, ...parsed, theme: parsed.theme ?? defaultState.theme, profile: { ...defaultState.profile, ...(parsed.profile ?? {}) }, authorProfiles: { ...defaultState.authorProfiles, ...(parsed.authorProfiles ?? {}) }, capsules: parsed.capsules ?? defaultState.capsules, journeyProgress: parsed.journeyProgress ?? defaultState.journeyProgress, helpfulReplies: parsed.helpfulReplies ?? defaultState.helpfulReplies, preferences: { ...defaultState.preferences, ...(parsed.preferences ?? {}) } }
  } catch { return defaultState }
}

